pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Attacker tries to withdraw
        address attacker = address(0xdead);
        vm.deal(attacker, 0);
        vm.prank(attacker);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: attacker cannot withdraw (Owner is deployer), so contract still has 1 ether
        // Modified: attacker can withdraw, so contract balance is 0
        assertEq(address(c).balance, 1 ether);
    }
}

